def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_pressures = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                pressure = bid / max(1.0, float(opp.get('daily_salary', DAILY_SALARY)))
                opp_pressures.append(pressure)

    if budget <= 0:
        return 0.0

    guaranteed_units = int(supply // WATER_REQ)
    alive_count = len(alive) + 1
    scarcity = guaranteed_units < alive_count

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if scarcity:
        urgency += 1
    if float(supply) <= 16.0:
        urgency += 1
    if day >= 8:
        urgency += 1

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_pressure = sum(opp_pressures) / len(opp_pressures) if opp_pressures else 0.0

    base = 0.0
    if urgency >= 6:
        base = DAILY_SALARY * 1.25
    elif urgency >= 4:
        base = DAILY_SALARY * 0.95
    elif urgency >= 2:
        base = DAILY_SALARY * 0.62
    else:
        base = DAILY_SALARY * 0.32

    if prev_bids:
        if highest_prev >= 130:
            if urgency <= 2:
                base = min(base, DAILY_SALARY * 0.28)
            else:
                base = max(base, DAILY_SALARY * 0.9)
        elif highest_prev >= 100:
            if urgency <= 1:
                base = min(base, DAILY_SALARY * 0.35)
            else:
                base = max(base, min(highest_prev * 0.82, DAILY_SALARY * 1.0))
        elif highest_prev >= 70:
            base = max(base, min(highest_prev + 2.0, DAILY_SALARY * 1.02))
        else:
            base = max(base, highest_prev + 3.0)

    if avg_pressure < 0.7 and urgency <= 2:
        base *= 0.9
    if avg_pressure > 1.2 and urgency <= 2:
        base *= 0.8

    if budget < DAILY_SALARY * 2:
        base = min(base, budget * 0.55)
    elif budget < DAILY_SALARY * 4 and urgency <= 2:
        base = min(base, DAILY_SALARY * 0.55)

    if no_water_days >= 2 or hp <= 2:
        base = max(base, DAILY_SALARY * 0.95)

    if guaranteed_units >= alive_count and urgency <= 2:
        base = min(base, DAILY_SALARY * 0.26)

    bid = max(0.0, min(float(budget), float(base)))
    return float(round(bid, 2))

